// PROBE (temporary): what the printer panel's model reads when the
// project cannot be saved and printer_change is called.
void probe_nozzle_change_when_saving_fails(const std::string& named)
{
    PresetCollection& printers = wxGetApp().preset_bundle->printers;
    PrinterSetup::OrcaPrinterBackend plain(*m_plater, PrinterSetup::PrinterCatalog::load(Slic3r::resources_dir()));
    const auto set_nozzle = [&](double nozzle) {
        PrinterSetup::ChangePrinterRequest request{named, nozzle};
        PrinterSetup::SavedPrinter         unused;
        std::vector<std::string>           dropped;
        return plain.change_printer(request, unused, dropped);
    };
    const auto parent = [&] {
        const Preset* profile = printer_profile(named);
        return profile == nullptr ? std::string() : profile->inherits();
    };
    auto* autosave = installed_shell()->autosave();
    const std::filesystem::path pending = std::filesystem::path(data_dir()) / "jusprin" / "projects" /
                                           persistence().document().project_id() / "pending";
    std::cerr << "HARNESS NOTE probe pending " << pending.string() << " exists " << std::filesystem::exists(pending) << '\n';
    const auto report = [&](const char* label, const Agent::ToolActivity* call) {
        std::cerr << "HARNESS NOTE probe " << label << " state "
                  << (call == nullptr ? "none" : Agent::to_string(call->state));
        if (call != nullptr && call->error)
            std::cerr << " code " << call->error->code << " message \"" << call->error->message << "\"";
        if (call != nullptr && call->state == Agent::ToolState::Succeeded)
            std::cerr << " result " << call->result_json;
        std::cerr << " autosave_state " << int(autosave->state()) << " autosave_error \"" << autosave->error()
                  << "\" parent \"" << parent() << "\" notes \""
                  << printers.get_edited_preset().config.opt_string("printer_notes") << "\"\n";
    };
    const auto original = std::filesystem::status(pending).permissions();
    const auto lock = [&] {
        std::filesystem::permissions(pending, std::filesystem::perms::owner_read | std::filesystem::perms::owner_exec,
                                     std::filesystem::perm_options::replace);
    };
    const auto unlock = [&] { std::filesystem::permissions(pending, original, std::filesystem::perm_options::replace); };

    // A: the project's printer, with an unsaved edit, and storage that
    // refuses writes.
    SetupCommands::select_printer_preset(*m_plater, named);
    printers.get_edited_preset().config.set_key_value("printer_notes", new ConfigOptionString("probe-a"));
    lock();
    const Agent::ToolActivity* a = call_in_panel(named, "printer_change", {{"printerName", named}, {"nozzle", 0.6}}, "probe_a");
    report("A_in_use_dirty_storage_refuses", a);
    check(a != nullptr && a->state == Agent::ToolState::Failed && parent() == kSetupFixturePrinter &&
              printers.get_edited_preset().config.opt_string("printer_notes") == "probe-a",
          "probe_a_nozzle_and_edit_stay");
    unlock();
    // The same call once storage recovers.
    const Agent::ToolActivity* a2 = call_in_panel(named, "printer_change", {{"printerName", named}, {"nozzle", 0.6}}, "probe_a2");
    report("A2_after_storage_recovers", a2);
    printers.discard_current_changes();
    if (parent() != kSetupFixturePrinter)
        set_nozzle(0.4);

    // B: a printer the project does not use; the project has an unsaved
    // change of its own, and storage refuses writes.
    SetupCommands::select_printer_preset(*m_plater, kSetupFixturePrinter);
    autosave->save_now();
    printers.get_edited_preset().config.set_key_value("printer_notes", new ConfigOptionString("probe-b"));
    lock();
    const Agent::ToolActivity* b = call_in_panel(named, "printer_change", {{"printerName", named}, {"nozzle", 0.6}}, "probe_b");
    report("B_not_in_use_storage_refuses", b);
    unlock();
    printers.discard_current_changes();
    if (parent() != kSetupFixturePrinter)
        set_nozzle(0.4);
    autosave->save_now();
}

